"""Settings contract additions, executed by build-openapi.py."""
sb = {'type': 'boolean'}
sdate = {'anyOf': [string(format='date-time'), {'type': 'null'}]}
S['SettingsWorkspace'] = obj({**fieldnames('id name description owner_id owner_name deployment_mode timezone language'), 'revision': integer(minimum=1), 'created_at': string(format='date-time'), 'updated_at': string(format='date-time')})
S['SettingsTeamProfile'] = obj({**fieldnames('owner_id owner_name department'), 'is_mock': sb, 'created_at': sdate, 'updated_at': sdate})
S['SettingsMember'] = obj({**S['Member']['properties'], 'is_mock': sb, 'team_ids': arr(string()), 'created_at': sdate})
S['SettingsApplication'] = obj(fieldnames('id name key'))
S['SettingsTeam'] = obj({**fieldnames('id name description'), **S['SettingsTeamProfile']['properties'], 'member_ids': arr(string()), 'applications': arr(obj(fieldnames('id name key permission relationship')))})
S['SettingsRole'] = obj({**fieldnames('id name description scope'), 'member_count': integer(), 'permissions': obj({k: sb for k in ['view', 'investigate', 'approve', 'execute', 'manage']})})
S['SettingsOverview'] = obj({'workspace': ref('SettingsWorkspace'), 'version': string(), 'can_manage': sb, 'integrations': arr(obj({'kind': string(), 'total': integer(), 'configured': integer(), 'state': string()})), 'capabilities': obj({k: sb for k in ['custom_roles', 'resource_acl', 'team_owners']})})
S['SettingsDirectory'] = obj({'members': arr(ref('SettingsMember')), 'teams': arr(ref('SettingsTeam')), 'roles': arr(ref('SettingsRole')), 'departments': arr(obj({'name': string(), 'member_count': integer(), 'team_count': integer()})), 'applications': arr(ref('SettingsApplication')), 'grants': arr(obj(fieldnames('application_id subject_type subject_id permission'))), 'mock_notice': string()})
route('get', '/settings/overview', 'Read workspace metadata and actual configuration counts', response=ref('SettingsOverview'), desc='Configuration is not health evidence. MCP counts restricted to admins. Version comes from server build metadata; preferences are workspace defaults only.')
route('patch', '/settings/overview', 'Save workspace metadata with optimistic revision', 'admin', obj({'name': string(minLength=1, maxLength=120), 'description': string(maxLength=200), 'timezone': string(), 'language': string(enum=['zh-CN']), 'revision': integer(minimum=1)}, ['revision']), ref('SettingsWorkspace'), desc='409 on stale revision. Owner, deployment mode, dates and version cannot be changed here. Unknown fields are rejected. Saves an audit record atomically.')
route('get', '/settings/directory', 'Aggregate real identity, team and application ACL records', 'admin', response=ref('SettingsDirectory'), desc='Mock identities are explicitly marked and database-constrained to disabled with empty passwords. Built-in roles remain authoritative; operator may approve within operate scope. Departments are existing text metadata, not an organization-tree ACL.')
route('patch', '/settings/teams/{id}/profile', 'Save team owner and department metadata', 'admin', obj(fieldnames('owner_id department'), ['owner_id', 'department']), ref('SettingsTeamProfile'), desc='Both fields must be explicitly provided and non-null. Nonempty owner must be an existing non-deleted team member. Ownership is metadata and does not confer application authority. Existing team/member/grant endpoints remain authoritative.')
